int main(void) {
    /* conversion machine -> reseau et retour, sur un port (16 bits) */
    unsigned short port = 7000;
    unsigned short reseau = htons(port);
    unsigned short retour = ntohs(reseau);

    printf("port   = %u\n", port);
    printf("retour = %u\n", retour);
    printf("egaux  = %s\n", (port == retour) ? "oui" : "non");

    /* une adresse IP, de la chaine pointee vers la struct in_addr et retour */
    struct in_addr adr;
    if (inet_aton("193.49.30.38", &adr) == 0) {
        printf("adresse invalide\n");
        return 1;
    }
    printf("adresse = %s\n", inet_ntoa(adr));

    /* inet_aton renvoie 0 sur une chaine invalide */
    struct in_addr autre;
    printf("chaine bidon : %d\n", inet_aton("999.0.0.1", &autre));
    return 0;
}

