#include <string.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main(int argc, char *argv[]) {
    if (argc < 3) { fprintf(stderr, "usage: %s ip port\n", argv[0]); return 1; }

    struct sockaddr_in adr;
    memset(&adr, 0, sizeof adr);

    /* === A COMPLETER ===
       1. sin_family : la famille AF_INET
       2. sin_port   : le port argv[2] (atoi), converti en ordre reseau avec htons
       3. sin_addr   : l'adresse argv[1], via inet_aton ; sortir en erreur si invalide */

    printf("famille AF_INET : %s\n", (adr.sin_family == AF_INET) ? "oui" : "non");
    /* ntohs : reconvertit le port de l'ordre reseau vers l'ordre machine */
    printf("port relu : %u\n", ntohs(adr.sin_port));
    printf("adresse : %s\n", inet_ntoa(adr.sin_addr));
    return 0;
}

