#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main(void) {
    int tube[2];
    pipe(tube);

    if (fork() == 0) {
        /* ENFANT = SERVEUR */
        close(tube[0]);
        int ec = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in a;
        memset(&a, 0, sizeof a);
        a.sin_family = AF_INET;
        a.sin_addr.s_addr = htonl(INADDR_ANY);
        a.sin_port = htons(0);
        bind(ec, (struct sockaddr *) &a, sizeof a);
        socklen_t lg = sizeof a;
        getsockname(ec, (struct sockaddr *) &a, &lg);
        unsigned short port = ntohs(a.sin_port);
        listen(ec, 5);
        write(tube[1], &port, sizeof port);
        close(tube[1]);
        printf("serveur : socle pret\n");
        int sv = accept(ec, NULL, NULL);
        char buf[64] = {0};
        recv(sv, buf, sizeof buf - 1, 0);
        printf("serveur recoit : %s\n", buf);
        send(sv, "ok", 2, 0);
        close(sv);
        close(ec);
        exit(0);
    }

    /* PARENT = CLIENT */
    close(tube[1]);
    unsigned short port;
    read(tube[0], &port, sizeof port);
    close(tube[0]);
    int sk = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in s;
    memset(&s, 0, sizeof s);
    s.sin_family = AF_INET;
    s.sin_port = htons(port);
    inet_aton("127.0.0.1", &s.sin_addr);
    connect(sk, (struct sockaddr *) &s, sizeof s);
    send(sk, "salut", 5, 0);
    char buf[64] = {0};
    recv(sk, buf, sizeof buf - 1, 0);
    printf("client recoit : %s\n", buf);
    close(sk);
    wait(NULL);
    return 0;
}

