    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        /* ENFANT = SERVEUR : sequence socket -> bind -> listen -> accept.
           Le squelette du serveur est COMPLET, ne pas le modifier. */
        close(tube[0]);
        int ec = socket(AF_INET, SOCK_STREAM, 0);
        if (ec == -1) { perror("socket"); exit(EXIT_FAILURE); }
        struct sockaddr_in adr;
        memset(&adr, 0, sizeof adr);
        adr.sin_family = AF_INET;
        adr.sin_addr.s_addr = htonl(INADDR_ANY);
        adr.sin_port = htons(0);
        if (bind(ec, (struct sockaddr *) &adr, sizeof adr) == -1) { perror("bind"); exit(EXIT_FAILURE); }
        socklen_t lg = sizeof adr;
        getsockname(ec, (struct sockaddr *) &adr, &lg);
        unsigned short port = ntohs(adr.sin_port);
        if (listen(ec, 5) == -1) { perror("listen"); exit(EXIT_FAILURE); }
        write(tube[1], &port, sizeof port);
        close(tube[1]);
        int sv = accept(ec, NULL, NULL);
        if (sv == -1) { perror("accept"); exit(EXIT_FAILURE); }
        char buf[128] = {0};
        ssize_t n = recv(sv, buf, sizeof buf - 1, 0);
        if (n > 0) {
            buf[n] = '\0';
            printf("serveur : recu = %s\n", buf);
            for (int i = 0; buf[i]; i++) buf[i] = (char) toupper((unsigned char) buf[i]);
            send(sv, buf, strlen(buf), 0);
        }
        close(sv);
        close(ec);
        exit(EXIT_SUCCESS);
    }

    /* PARENT = CLIENT : a completer.
       Le port du serveur arrive par le tube. */
    close(tube[1]);
    unsigned short port;
    if (read(tube[0], &port, sizeof port) != (ssize_t) sizeof port) { perror("read"); exit(EXIT_FAILURE); }
    close(tube[0]);

    /* === A COMPLETER : le CLIENT ===
       1. creer une socket TCP
       2. remplir une struct sockaddr_in visant 127.0.0.1 sur 'port'
       3. connect au serveur
       4. envoyer argv[1] avec send
       5. recevoir la reponse et l'afficher : "client : recu = <reponse>" */

    wait(NULL);
    return 0;
}

