#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

/* Le serveur envoie 10 octets en deux fois. Le client lit en BOUCLE. */
int main(void) {
    int tube[2];
    pipe(tube);

    if (fork() == 0) {
        close(tube[0]);
        int ec = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in a;
        memset(&a, 0, sizeof a);
        a.sin_family = AF_INET;
        a.sin_addr.s_addr = htonl(INADDR_ANY);
        a.sin_port = htons(0);
        bind(ec, (struct sockaddr *) &a, sizeof a);
        socklen_t lg = sizeof a;
        getsockname(ec, (struct sockaddr *) &a, &lg);
        unsigned short port = ntohs(a.sin_port);
        listen(ec, 5);
        write(tube[1], &port, sizeof port);
        close(tube[1]);
        int sv = accept(ec, NULL, NULL);
        /* deux envois separes : TCP n'a pas de frontiere de message */
        send(sv, "ABCDE", 5, 0);
        send(sv, "12345", 5, 0);
        close(sv);
        close(ec);
        exit(0);
    }

    close(tube[1]);
    unsigned short port;
    read(tube[0], &port, sizeof port);
    close(tube[0]);
