#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

/* Le client envoie DEUX datagrammes ; le serveur en lit DEUX. */
int main(void) {
    int tube[2];
    pipe(tube);

    if (fork() == 0) {
        /* ENFANT = SERVEUR UDP */
        close(tube[0]);
        int sk = socket(AF_INET, SOCK_DGRAM, 0);
        struct sockaddr_in a;
        memset(&a, 0, sizeof a);
        a.sin_family = AF_INET;
        a.sin_addr.s_addr = htonl(INADDR_ANY);
        a.sin_port = htons(0);
        bind(sk, (struct sockaddr *) &a, sizeof a);
        socklen_t lg = sizeof a;
        getsockname(sk, (struct sockaddr *) &a, &lg);
        unsigned short port = ntohs(a.sin_port);
        write(tube[1], &port, sizeof port);
        close(tube[1]);

        struct sockaddr_in cli;
        socklen_t lc = sizeof cli;
        char buf[64];

        /* premier datagramme */
        ssize_t n1 = recvfrom(sk, buf, sizeof buf, 0,
                              (struct sockaddr *) &cli, &lc);
        printf("recu 1 : %zd octets\n", n1);

        /* second datagramme : un recvfrom = un sendto */
        ssize_t n2 = recvfrom(sk, buf, sizeof buf, 0,
                              (struct sockaddr *) &cli, &lc);
        printf("recu 2 : %zd octets\n", n2);

        /* on repond a l'emetteur du dernier datagramme */
        sendto(sk, "ok", 2, 0, (struct sockaddr *) &cli, lc);
        close(sk);
        exit(0);
    }

    /* PARENT = CLIENT UDP */
    close(tube[1]);
    unsigned short port;
    read(tube[0], &port, sizeof port);
    close(tube[0]);
    int sk = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in s;
    memset(&s, 0, sizeof s);
    s.sin_family = AF_INET;
    s.sin_port = htons(port);
    inet_aton("127.0.0.1", &s.sin_addr);

    /* deux envois de tailles differentes */
    sendto(sk, "abcde", 5, 0, (struct sockaddr *) &s, sizeof s);
    sendto(sk, "XYZ", 3, 0, (struct sockaddr *) &s, sizeof s);

    char rep[64] = {0};
    struct sockaddr_in src;
    socklen_t ls = sizeof src;
    ssize_t r = recvfrom(sk, rep, sizeof rep - 1, 0,
                         (struct sockaddr *) &src, &ls);
    rep[r] = '\0';
    printf("reponse : %s\n", rep);
    close(sk);
    wait(NULL);
    return 0;
}

