#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define NB_CLIENTS 3

/* execute par chaque ENFANT du serveur : double la valeur recue */
static void traiter_client(int sk) {
    char buf[64] = {0};
    ssize_t n = recv(sk, buf, sizeof buf - 1, 0);
    if (n > 0) {
        buf[n] = '\0';
        char rep[64];
        snprintf(rep, sizeof rep, "%d", atoi(buf) * 2);
        send(sk, rep, strlen(rep), 0);
    }
}

/* un client : envoie 'valeur', recoit le double, le renvoie par 'sortie' */
static void client(unsigned short port, int valeur, int sortie) {
    int sk = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in srv;
    memset(&srv, 0, sizeof srv);
    srv.sin_family = AF_INET;
    srv.sin_port = htons(port);
    inet_aton("127.0.0.1", &srv.sin_addr);
    connect(sk, (struct sockaddr *) &srv, sizeof srv);
    char msg[64];
    snprintf(msg, sizeof msg, "%d", valeur);
    send(sk, msg, strlen(msg), 0);
    char buf[64] = {0};
    ssize_t n = recv(sk, buf, sizeof buf - 1, 0);
    int recu = (n > 0) ? atoi(buf) : -1;
    write(sortie, &recu, sizeof recu);
    close(sk);
    exit(EXIT_SUCCESS);
}

int main(void) {
    int tube[2];
    pipe(tube);

    pid_t serveur = fork();
    if (serveur == 0) {
        /* SERVEUR CONCURRENT : un fork par client */
        close(tube[0]);
        signal(SIGCHLD, SIG_IGN);
        int ec = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in a;
        memset(&a, 0, sizeof a);
        a.sin_family = AF_INET;
        a.sin_addr.s_addr = htonl(INADDR_ANY);
        a.sin_port = htons(0);
        bind(ec, (struct sockaddr *) &a, sizeof a);
        socklen_t lg = sizeof a;
        getsockname(ec, (struct sockaddr *) &a, &lg);
        unsigned short port = ntohs(a.sin_port);
        listen(ec, 5);
        write(tube[1], &port, sizeof port);
        close(tube[1]);
        for (int i = 0; i < NB_CLIENTS; i++) {
            int sk = accept(ec, NULL, NULL);
            if (fork() == 0) {
                close(ec);
                traiter_client(sk);
                close(sk);
                exit(EXIT_SUCCESS);
            }
            close(sk);
        }
        close(ec);
        exit(EXIT_SUCCESS);
    }

    /* PROGRAMME PRINCIPAL */
    close(tube[1]);
    unsigned short port;
    read(tube[0], &port, sizeof port);
    close(tube[0]);

    int valeurs[NB_CLIENTS] = {10, 20, 30};
    for (int i = 0; i < NB_CLIENTS; i++) {
        int recu = 0;
        int rr[2];
        pipe(rr);                 /* tube pour recuperer le resultat du client */
        pid_t cl = fork();
        if (cl == 0) {
            close(rr[0]);
            client(port, valeurs[i], rr[1]);
        }
        close(rr[1]);
        read(rr[0], &recu, sizeof recu);
        close(rr[0]);
        waitpid(cl, NULL, 0);     /* attendre CE client avant de lancer le suivant */
        printf("client %d : envoie %d, recoit %d\n", i + 1, valeurs[i], recu);
        fflush(stdout);           /* vider le tampon AVANT le prochain fork */
    }

    waitpid(serveur, NULL, 0);
    printf("serveur : %d clients servis\n", NB_CLIENTS);
    return 0;
}

